                    let m = i / 3;
                    assert(i == 3 * m);
                    assert(i < P);
                    assert(m < k);
                    assert(m + 1 <= k);
                    assert(3 * (m + 1) <= 3 * k);
                    assert(i + 3 <= P);
                    assert(i + 2 < P);
                    assert(P <= L);
